"""Participant-first curriculum: one case, ten lessons, work in real accounts."""
import json
from pathlib import Path

def demo(title,action,prompt='',see='',asset=''):
 return dict(title=title,action=action,prompt=prompt,see=see,asset=asset)
def lesson(id,time,title,short,tools,minutes,why,principle,story,outcome,skills,demos,mission,steps,checks,hints,question,files,bonus,carry):
 return locals()
lessons=[
lesson('posteingang','08:30','Erst verstehen. Dann loslegen.','Eine Mail kommt rein.',['chatgpt','outlook'],50,
 'Mara Sommer möchte zwei Büroräume umbauen lassen. Bevor du antwortest, brauchst du einen Überblick: Was ist gewünscht? Welche Angaben fehlen? Was ist jetzt deine Aufgabe?',
 'ChatGPT braucht einen klaren Auftrag.',
 'Du musst keine besondere Sprache lernen. Nenne das Ziel, die passenden Informationen und das gewünschte Ergebnis. „Erkläre mir diese Mail in drei einfachen Sätzen“ ist schon ein guter Anfang. Ein Plugin ist dabei die Verbindung zu einem Programm, zum Beispiel Outlook.',
 'Eine verständliche Zusammenfassung und drei offene Fragen.',
 ['ChatGPT öffnen; Modell wählen; eine Aufgabe starten und fortsetzen','Outlook-Verbindung und richtiges Konto erkennen','Mails nach Zeitraum, Absender oder Betreff finden und auswählen','Mail erklären lassen; Anhänge erkennen und gezielt lesen','Mit einer Nachfrage korrigieren, ohne neu anzufangen'],
 [demo('Öffne ChatGPT und wähle dein Modell.','Öffne die ChatGPT-Desktop-App. Für die Aufgaben verwenden wir den Bereich, der in der App als Work beschriftet ist. Klicke auf den Modellnamen neben dem Eingabefeld. Unsere Empfehlung für das Seminar: GPT-6 Astra, Denkaufwand Low (niedrig), sofern verfügbar. Ein Modell ist die KI, die deinen Auftrag bearbeitet. Low ist die Denkstufe, kein anderes Modell. Wenn Astra fehlt, lass Kerim die passende verfügbare Alternative zeigen. Prüfe anschließend unter Plugins die Outlook-Verbindung.',see='Alle finden die Modellauswahl und kennen ihr ausgewähltes Modell. Die verfügbaren Optionen hängen vom Konto ab.',asset='work-original.png'),
 demo('Finde die heutige Mail.','Lass Absender und Betreff anzeigen. Wähle dann selbst eine konkrete Mail aus. Für die Vorführung nutzt du eine vorbereitete Testmail oder die Lindenhof-Datei.','Zeige mir die Mails, die ich heute bekommen habe, mit Absender und Betreff. Ich wähle danach eine aus.','Die Gruppe kann eine gefundene Mail eindeutig benennen.'),
 demo('Lass sie dir erklären.','Öffne die gewählte Mail und lass dir den Wunsch des Absenders erklären. Ein Anhang wird nur dann gelesen, wenn er für die Aufgabe relevant ist.','Erkläre mir die Mail von Mara Sommer zur Besichtigung in drei einfachen Sätzen. Was möchte sie von mir? Welche Angaben fehlen? Noch keine Antwort versenden.','Zwei Büroräume, zwei Innentüren, Besichtigung gewünscht; Maße und Zugang sind offen.'),
 demo('Verbessere die Antwort.','Zeige eine echte Folgefrage in derselben Aufgabe. Vergleiche die neue Antwort mit der Mail.','Das ist mir noch zu kompliziert. Erkläre es ohne Fachwörter und nenne nur meinen nächsten Schritt.','Die Antwort wird verständlicher. Keine neue Aufgabe ist nötig.')],
 'Wähle eine passende Mail, die du heute erhalten hast. Lass sie erklären und verbessere die Erklärung mit einer eigenen Nachfrage. Danach starten wir alle mit dem gemeinsamen Fall Lindenhof.',
 ['Öffne ChatGPT und wähle eine heutige Mail aus, die du für diese Übung verwenden darfst.','Lass dir sagen, was der Absender braucht und was noch fehlt.','Ändere Länge oder Sprache mit einer Nachfrage. Vergleiche die Erklärung mit der Originalmail.','Öffne anschließend die fiktive Lindenhof-Anfrage. Sie ist ab jetzt unser gemeinsamer Auftrag.'],
 ['Ich kann den Inhalt meiner gewählten Mail mit eigenen Worten erklären.','Ich habe die Antwort einmal gezielt verbessert.','Ich kenne bei Lindenhof mindestens drei offene Angaben.'],
 ['Beginne mit einer kleinen Frage: „Was möchte der Absender von mir?“','Nenne Absender und Betreff. Bei mehreren Treffern wähle zuerst die richtige Mail.','Keine passende Mail oder keine Verbindung? Lade 03-lindenhof.txt in ChatGPT hoch. Das Lernziel bleibt gleich.'],
 dict(ask='ChatGPT schreibt: „Die Besichtigung ist für Dienstag bestätigt.“ In der Mail steht nur ein Terminwunsch. Was tust du?',options=['Übernehmen, die Formulierung klingt sicher.','Die Stelle mit der Mail vergleichen und korrigieren lassen.'],correct=1,explain='Eine sichere Formulierung ist kein Beleg. Du gibst ChatGPT die fehlende Grenze: Der Termin ist noch nicht bestätigt.'),
 ['03-lindenhof.txt'], 'Lass dir einen relevanten Mailanhang erklären. Sage ausdrücklich, welche Datei du meinst.', 'Die Lindenhof-Anfrage begleitet uns durch den ganzen Tag.'),
lesson('projekt','09:00','Ein Zuhause für deinen Auftrag.','Lindenhof wird ein Projekt.',['chatgpt'],50,
 'Zur Kundenanfrage kommen später Recherche, Tabellen und Antworten hinzu. Wenn alles in einzelnen Aufgaben verschwindet, musst du den Hintergrund immer wieder zusammensuchen.',
 'Ein Projekt ist deine Arbeitsmappe.',
 'Die Mappe gehört zu einem Kundenauftrag. Darin liegen Unterlagen, Gespräche und gemeinsame Vorgaben. Ein Gespräch erledigt eine einzelne Aufgabe. Das Projekt hält mehrere solcher Aufgaben zusammen. Für einen anderen Kunden beginnst du eine neue Mappe.',
 'Dein eigenes Projekt „Lindenhof · Umbau“ mit Quelle, Vorgabe und erster ChatGPT-Aufgabe.',
 ['Projekt und einzelne Aufgabe unterscheiden','Projekt anlegen und sinnvoll benennen','Dateien als Projektquellen hinzufügen','Projekthinweise speichern und später ändern','ChatGPT-Aufgabe im richtigen Projekt starten und wiederfinden'],
 [demo('Lege die Mappe an.','Öffne die Seitenleiste und wähle Neues Projekt. Nenne es „Lindenhof · Umbau“. In der englischen Originalabbildung heißt der Eintrag New project.',see='Das neue Projekt ist in der Seitenleiste sichtbar.',asset='projects-sidebar.webp'),
 demo('Füge die Kundenanfrage hinzu.','Öffne die Dateien beziehungsweise Quellen des Projekts. Füge 03-lindenhof.txt hinzu. Zeige den Dateinamen anschließend in der Projektübersicht.',see='Die Unterlage liegt im Projekt, nicht nur in einem beliebigen Einzelchat.',asset='project-overview.webp'),
 demo('Speichere gemeinsame Vorgaben.','Öffne das Menü mit den drei Punkten und die Projekteinstellungen. Hinterlege die folgende Vorgabe. Erkläre, dass sie für diesen Auftrag gilt.','Wir bearbeiten Lindenhof. Schreibe Kundenantworten freundlich und kurz, mit „Sie“. Erfinde keine Maße, Preise oder Termine. Kennzeichne fehlende Angaben als „noch offen“.','Die Vorgabe ist gespeichert und lässt sich wieder öffnen.',asset='project-settings.webp'),
 demo('Starte Arbeit in der Mappe.','Wähle im Projekt ChatGPT. Prüfe den Projektnamen und starte eine Zusammenfassung. Öffne danach kurz eine andere Ansicht und finde die Aufgabe im Projekt wieder.','Fasse die Lindenhof-Unterlagen zusammen. Trenne bestätigte Angaben, widersprüchliche Angaben und offene Fragen. Nenne die jeweilige Quelle.','Die alte Notiz nennt drei Türen; die aktuelle Anfrage nennt zwei. Der Widerspruch bleibt sichtbar.')],
 'Lege dein eigenes Projekt „Lindenhof · Umbau“ an. Füge die Anfrage hinzu, speichere eine Kommunikationsvorgabe und starte darin eine Zusammenfassung.',
 ['Erstelle das Projekt in deiner ChatGPT-Umgebung.','Füge 03-lindenhof.txt als Projektquelle hinzu.','Speichere deine Vorgabe für kurze, sachliche Kundenantworten.','Lass die Unterlagen zusammenfassen. Verlasse die Ansicht und finde Projekt und Aufgabe wieder.'],
 ['Ich finde das Projekt, die Datei und die Vorgabe wieder.','Meine Aufgabe ist dem Projekt Lindenhof zugeordnet.','Die Zusammenfassung unterscheidet die alte Notiz von der aktuellen Anfrage.'],
 ['Denk an einen normalen Projektordner. Als Namen reicht „Lindenhof · Umbau“.','Suche im Projekt nach Dateien oder Quellen. Bezeichnungen können je nach Oberfläche abweichen.','Nutze als erste Aufgabe: „Was wissen wir sicher? Was fehlt? Welche Angaben widersprechen sich?“'],
 dict(ask='Morgen fragt ein ganz anderer Kunde nach einem Dachausbau. Wo beginnst du?',options=['Im Projekt Lindenhof – dort ist schon alles eingerichtet.','In einem eigenen Projekt für den neuen Auftrag.'],correct=1,explain='Ein eigenes Projekt hält Quellen und Vorgaben auseinander. So vermischen sich die beiden Kundenaufträge nicht.'),
 ['03-lindenhof.txt'],'Ändere eine Projekthinweis-Formulierung und prüfe die Wirkung in einer neuen Aufgabe.','Alle folgenden ChatGPT-Aufgaben gehören in dieses Projekt.'),
lesson('dateien','09:30','Die richtige Datei. Am richtigen Ort.','Unterlagen finden und bearbeiten.',['onedrive','word','chatgpt'],70,
 'Die Anfrage liegt im Projekt. Für die weitere Arbeit brauchst du eine kurze, bearbeitbare Übersicht – und einen Ordner, in dem du Ergebnisse wiederfindest.',
 'Datei, Format und Speicherort sind drei verschiedene Dinge.',
 'Der Inhalt ist das, was in der Datei steht. Das Format bestimmt, wie du damit weiterarbeitest: Word zum Bearbeiten, PDF zum Weitergeben, Excel zum Rechnen. OneDrive ist ein Speicherort. Eine Datei in ChatGPT hochzuladen bedeutet nicht automatisch, dass sie auch in OneDrive gespeichert ist.',
 'Ein bearbeitbarer Projektbrief und eine PDF-Kopie im eigenen OneDrive-Übungsordner.',
 ['OneDrive-Verbindung prüfen; ChatGPT einen eigenen Ordner anlegen lassen; Dateien suchen und öffnen','Lokale Datei hochladen, Ergebnis herunterladen und wieder öffnen','Inhalt gezielt ändern, Original erhalten und Versionen benennen','TXT als DOCX aufbereiten und DOCX als PDF ausgeben','Ergebnis in OneDrive hochladen; umbenennen oder verschieben; Speicherort prüfen'],
 [demo('Lass ChatGPT deinen Ordner anlegen.','Beauftrage ChatGPT direkt, über die OneDrive-Verbindung einen eigenen Übungsordner anzulegen. Öffne anschließend den angelegten Ordner und prüfe das Konto.','Lege in meinem OneDrive einen neuen Ordner „Seminar Lindenhof“ für meine Seminarübungen an. Falls dieser Name schon vergeben ist, frage mich nach einem anderen Namen. Zeige mir anschließend den Link zum neu angelegten Ordner.','Der von ChatGPT angelegte Ordner lässt sich in deinem eigenen OneDrive öffnen.'),
 demo('Lass ChatGPT die Anfrage ablegen.','Lade 03-lindenhof.txt vom Seminarpaket in ChatGPT hoch. Beauftrage ChatGPT, diese Datei im gerade angelegten Ordner zu speichern. Öffne die gespeicherte Datei in OneDrive.','Speichere die hier hochgeladene Datei 03-lindenhof.txt unverändert in dem OneDrive-Ordner, den du gerade für meine Seminarübungen angelegt hast. Überschreibe keine vorhandene Datei. Zeige mir danach den Speicherort und die Datei.','Die Anfrage liegt im neuen Ordner und lässt sich dort öffnen.'),
 demo('Mach einen Projektbrief daraus.','Nutze die Anfrage als Quelle. Erzeuge eine neue Word-Datei, damit das Original erhalten bleibt.','Erstelle aus der Lindenhof-Anfrage einen einseitigen Projektbrief als DOCX. Gliedere in Auftrag, bestätigte Angaben und offene Fragen. Widersprüche nicht auflösen, sondern benennen. Dateiname: Lindenhof_Projektbrief_v1.docx.','Eine bearbeitbare Datei ist verfügbar.'),
 demo('Ändere gezielt den Inhalt.','Öffne die Datei und lasse einen Abschnitt ändern. Speichere die neue Fassung unter einem neuen Namen.','Ergänze im Projektbrief den Abschnitt „Vor der Besichtigung klären“ mit Türmaßen, Zugang und Ansprechpartner vor Ort. Erhalte die übrigen Inhalte. Speichere als Lindenhof_Projektbrief_v2.docx.','v1 bleibt erhalten, v2 enthält die Ergänzung.'),
 demo('Wechsle das Format.','Bitte zusätzlich um eine PDF-Ausgabe. Öffne beide Dateien. Erkläre: Die Endung umzubenennen wäre noch keine echte Umwandlung.','Erzeuge zusätzlich eine gut lesbare PDF aus Lindenhof_Projektbrief_v2.docx. Behalte die Word-Datei. Prüfe, dass keine Abschnitte fehlen.','DOCX ist bearbeitbar; PDF hat den gleichen Inhalt und ein lesbares Layout.'),
 demo('Lege das Ergebnis ab.','Lade die fertigen Dateien in den OneDrive-Übungsordner. Das geht über das eingerichtete Plugin oder direkt in OneDrive. Öffne sie dort und zeige den Speicherort.','Speichere die fertige Word-Datei und PDF im OneDrive-Übungsordner „Seminar Lindenhof“. Überschreibe keine vorhandene Datei. Zeige mir die gespeicherten Dateien.','Die Dateien sind in OneDrive vorhanden; ein Download allein genügt nicht.')],
 'Erstelle einen Projektbrief aus der Anfrage, verbessere einen Abschnitt und speichere ihn als Word-Datei und PDF in deinem OneDrive-Übungsordner.',
 ['Lass ChatGPT in deinem OneDrive einen eigenen Übungsordner anlegen. Öffne den Ordner zur Kontrolle.','Lade die Lindenhof-Anfrage in ChatGPT hoch und lass sie im neuen Ordner speichern. Öffne die Datei dort.','Lass einen Word-Projektbrief erstellen und öffne ihn.','Ändere einen Inhalt gezielt und speichere eine neue Version.','Erzeuge eine PDF-Kopie. Öffne beide Formate und vergleiche sie.','Speichere die Ergebnisse in deinem eigenen OneDrive-Übungsordner.'],
 ['ChatGPT hat meinen eigenen OneDrive-Übungsordner angelegt; ich kann ihn öffnen.','Meine Originalquelle ist erhalten.','Word und PDF lassen sich öffnen und enthalten dieselben bestätigten Angaben.','Ich kann den OneDrive-Speicherort zeigen.'],
 ['Sag ausdrücklich „als bearbeitbare Word-Datei“ oder „als PDF“.','Bei einem unlesbaren PDF: bitte um weniger Spalten, größere Schrift und erneute Ausgabe.','Wenn das Plugin keine Datei speichern kann, lade sie herunter und in OneDrive hoch. Prüfe das Ergebnis dort.'],
 dict(ask='Du hast einen Projektbrief in ChatGPT heruntergeladen. Liegt er damit schon in OneDrive?',options=['Ja, jeder Download landet automatisch dort.','Nur wenn ich ihn dort gespeichert und wiedergefunden habe.'],correct=1,explain='Ein Download landet meist zuerst auf deinem Computer. Speicherort und Dateiformat sind unabhängig voneinander.'),
 ['03-lindenhof.txt'],'Benenne eine Kopie eindeutig um und verschiebe sie in einen Unterordner „Freigabe“. Öffentliche Freigabelinks gehören nicht zur Grundübung.','Der geprüfte Projektbrief wird später ausgefüllt und an einen Antwortentwurf angehängt.'),
lesson('recherche','10:30','Erst nachsehen. Dann glauben.','Informationen mit Quellen sammeln.',['chatgpt'],55,
 'Für Lindenhof fehlen noch technische Angaben. Du kannst vor der Besichtigung recherchieren, welche Informationen ein Anbieter für eine passende Innentür benötigt. Die Recherche ersetzt keine fachliche Freigabe.',
 'Eine Antwort ist erst mit ihrer Quelle prüfbar.',
 'Bei Recherche sammelt ChatGPT Informationen. Bei Browserbedienung führt es Schritte auf einer Website aus. Du steuerst beides mit einem klaren Ziel. Gute Ergebnisse zeigen Links, trennen Fakten von Annahmen und lassen Unbekanntes offen.',
 'Eine kurze Recherche mit zwei überprüften Quellen und Fragen für die Besichtigung.',
 ['Suchziel, Umfang und gewünschte Quellen festlegen','Zwei Originalquellen öffnen und Aussagen vergleichen','Veröffentlichung, Aktualität und fehlende Angaben erkennen','Browser im nächsten Einzelschritt anweisen; bei Hängern stoppen und Stand klären','Recherche als Datei sichern und dem Projekt hinzufügen'],
 [demo('Stelle eine begrenzte Recherchefrage.','Lass ChatGPT bei Hersteller- oder Händlerquellen nachsehen. Halte die Aufgabe klein und fordere Links.','Recherchiere anhand von zwei Hersteller- oder Händlerquellen, welche Angaben für die Auswahl einer Innentür benötigt werden. Erstelle Fragen für die Besichtigung bei Lindenhof. Zeige die Quellen. Triff keine technische Eignungsentscheidung.','Die Antwort enthält prüfbare Links und offene Fragen.'),
 demo('Öffne die Quellen.','Öffne mit der Gruppe einen Originaltreffer. Suche die konkrete Passage. Prüfe, ob die Aussage tatsächlich dort steht.','Zeige mir bei der ersten Quelle die Stelle zu den benötigten Maßen. Wenn sie dort nicht steht, korrigiere die Zusammenfassung.','Eine Aussage wird direkt an ihrer Quelle geprüft.'),
 demo('Führe den Browser in einem kleinen Schritt.','Zeige die geöffnete Seite am Beamer. Gib einen einzelnen Folgeauftrag, der sich auf die sichtbare Seite bezieht.','Suche auf dieser Seite nach den Maßangaben und erkläre mir die Tabelle. Keine Anfrage absenden und nichts bestellen.','Die Gruppe erkennt den Unterschied zwischen Lesen und einer Handlung auf der Website.'),
 demo('Sichere nur die relevanten Ergebnisse.','Speichere eine kurze Liste mit Quellenlinks und offenen Fragen im Projekt.','Erstelle eine kurze Recherche-Notiz für Lindenhof mit den zwei Quellenlinks, Abrufdatum und offenen Fragen. Keine unbelegten Empfehlungen.','Die Notiz ist wieder auffindbar und bleibt nachvollziehbar.')],
 'Finde mit ChatGPT zwei geeignete Originalquellen und leite daraus Fragen für die Besichtigung ab. Prüfe mindestens eine Aussage selbst auf der Website.',
 ['Formuliere eine begrenzte Recherchefrage.','Öffne zwei Quellen und prüfe eine konkrete Aussage.','Gib im Browser einen kleinen Folgeauftrag.','Speichere die nützlichen Ergebnisse samt Links im Projekt.'],
 ['Ich kann die Originalquelle zu einer Aussage öffnen.','Meine Notiz trennt belegte Informationen von offenen Fragen.','Es wurde kein Anbieter kontaktiert und nichts bestellt.'],
 ['Beginne mit „Welche Maße muss ich vor einer Türbestellung aufnehmen?“','Wenn eine Seite blockiert, nutze eine andere zugängliche Originalquelle. Sage, welche Information fehlt.','Wenn der Browser hängt: „Stopp. Was ist schon erledigt? Was brauchst du für den nächsten Schritt?“'],
 dict(ask='ChatGPT nennt eine Eigenschaft, aber die verlinkte Seite bestätigt sie nicht. Was gehört in deine Notiz?',options=['Die Eigenschaft als Tatsache.','Die Eigenschaft als ungeklärt oder gar nicht.'],correct=1,explain='Ein Link neben einer Aussage ist noch kein Beleg. Du prüfst, ob die Quelle genau diese Aussage stützt.'),
 ['09-rechercheauftrag.txt'],'Als freies Browserbeispiel: Suche auf ImmoScout24 nach Büro und Lager. Vergleiche die Anzeigen, kontaktiere niemanden.','Die Recherchefragen fließen in den Projektbogen und die Besichtigungsagenda ein.'),
lesson('excel','11:30','Zahlen verstehen. Entscheidungen prüfen.','Drei Materialangebote vergleichen.',['excel','chatgpt'],70,
 'Für eine fiktive Montageposition liegen drei Angebote vor. Der niedrigste Stückpreis ist nicht unbedingt das günstigste Gesamtangebot. Deshalb vergleichen wir Menge, Preis und Lieferung gemeinsam.',
 'Sag, was die Tabelle beantworten soll.',
 'Du kannst eine Arbeitsmappe in ChatGPT hochladen oder mit der eingerichteten ChatGPT-Erweiterung direkt in Excel arbeiten. In beiden Fällen musst du wissen, welche Werte und Annahmen verwendet werden. Die KI kann rechnen und erklären; du prüfst mindestens eine Zeile selbst.',
 'Ein nachvollziehbarer Vergleich für 100 und 200 Einheiten mit Formeln und offenen Bedingungen.',
 ['Arbeitsmappe hochladen oder direkt in Excel bearbeiten','Blätter erklären lassen und Rohdaten bereinigen, Original erhalten','Formeln ergänzen, Lieferkosten einbeziehen und Fehler erkennen','Menge ändern; Auswirkungen erklären; Ergebnis stichprobenartig prüfen','XLSX speichern; Vergleich bei Bedarf als PDF oder CSV ausgeben'],
 [demo('Öffne die Arbeitsmappe.','Zeige Angebote, Materialliste und Rechenbeispiel. Lass erklären, welche Spalten für den Vergleich gebraucht werden.','Erkläre die Arbeitsmappe 04-materialvergleich.xlsx. Welche Angaben brauche ich, um die drei Angebote fair zu vergleichen? Ändere noch nichts.','Menge, Stückpreis, Lieferung und Lieferzeit werden benannt.'),
 demo('Bereinige eine Kopie.','Zeige die unterschiedlichen Schreibweisen und die als Text gespeicherte Menge. Lass das Original erhalten.','Bereinige die Materialliste in einer Kopie: vereinheitliche die Bezeichnung Montageeinheit und die Einheit Stück. Prüfe die Mengen als Zahlen. Verändere die Originaldaten nicht.','40 + 30 + 30 ergibt 100 Einheiten; andere Materialien bleiben getrennt.'),
 demo('Vergleiche die Gesamtkosten.','Lass eine Formel für Menge mal Stückpreis plus Lieferung ergänzen. Rechne Angebot B gemeinsam nach.','Vergleiche 100 Einheiten mit Formeln. Rechne die Lieferkosten dazu. Zeige Gesamtkosten netto, günstigstes Angebot und offene Lieferbedingungen.','A: 1.330 €, B: 1.310 €, C: 1.350 €. B ist bei 100 Einheiten am günstigsten.'),
 demo('Ändere die Menge.','Erhöhe auf 200. Benenne ausdrücklich die Annahme gleichbleibender Lieferkosten. Zeige, dass sich das Ergebnis ändern kann.','Berechne zusätzlich 200 Einheiten. Nimm nur für dieses Rechenbeispiel unveränderte Lieferkosten an. Welches Angebot ist dann am günstigsten?','A: 2.580 €, B: 2.600 €, C: 2.540 €. C ist rechnerisch günstiger; Lieferzeit und Eignung bleiben zu prüfen.'),
 demo('Zeige den zweiten Arbeitsweg.','Öffne dieselbe Datei direkt in Excel mit der eingerichteten ChatGPT-Erweiterung. Wiederhole eine kleine Änderung und prüfe die Zellen.',see='Die Gruppe kennt beide Wege und weiß, wo Änderungen gespeichert wurden.')],
 'Vergleiche die Angebote für 100 Einheiten und danach für 200. Erkläre einer anderen Person, warum sich der günstigste Anbieter verändert.',
 ['Öffne die Übungsmappe in ChatGPT oder direkt in Excel.','Bereinige die Materialliste in einer Kopie und ergänze nachvollziehbare Formeln.','Vergleiche 100 und 200 Einheiten einschließlich Lieferung.','Rechne eine Zeile selbst nach und speichere das Ergebnis. Probiere eine Änderung auch über den zweiten Weg.'],
 ['Für 100 Einheiten ist B mit 1.310 € netto am günstigsten.','Für 200 Einheiten ist C mit 2.540 € netto am günstigsten, bei unveränderter Lieferung.','Formeln, Annahmen und offene Lieferbedingungen sind sichtbar.'],
 ['Die Formel lautet Menge × Stückpreis + Lieferung.','Bei 100 Stück: 100 × 12,90 € + 20 € = 1.310 €.','Bei 200 Stück hat C 200 × 11,90 € + 160 € = 2.540 €. Der günstigste Preis beweist noch keine Eignung.'],
 dict(ask='C hat den niedrigsten Stückpreis. Ist C bei 100 Einheiten auch insgesamt am günstigsten?',options=['Ja, der Stückpreis reicht zum Vergleich.','Nein, mit Lieferung ist B günstiger.'],correct=1,explain='C kostet insgesamt 1.350 €, B nur 1.310 €. Die Lieferkosten verändern den Vergleich.'),
 ['04-materialvergleich.xlsx'],'Erzeuge eine PDF-Vergleichsübersicht oder eine CSV-Kopie. Prüfe: CSV enthält keine mehreren Tabellenblätter, Formatierungen oder Excel-Formeln wie die XLSX-Datei.','Der geprüfte Vergleich bleibt interne Entscheidungshilfe. Noch kein verbindliches Kundenangebot.'),
lesson('dokument','13:00','Aus Unterlagen wird ein fertiges Dokument.','Den Projektbogen ausfüllen.',['word','chatgpt'],60,
 'Du hast Kundenangaben, offene Fragen und recherchierte Informationen gesammelt. Jetzt sollen die passenden Angaben in den vorbereiteten Projektbogen. Du musst sie nicht Feld für Feld übertragen.',
 'Die Vorlage gibt die Form vor. Die Quelle liefert die Fakten.',
 'Gib ChatGPT beides: die leere Vorlage und die geprüften Angaben. Sage, was unverändert bleiben soll. Fehlende Informationen bleiben offen. Anschließend öffnest du die fertige Datei und prüfst Inhalt und Layout – nicht nur die kurze Antwort in ChatGPT.',
 'Ein ausgefüllter Projektbogen als DOCX und geprüfte PDF-Kopie.',
 ['Vorlage und mehrere Quellen gemeinsam übergeben','Quellenkonflikte sichtbar lassen; keine Angaben erfinden','Inhalte ändern, Abschnitte ergänzen und Layout erhalten','Bearbeitbare Ausgabe plus PDF erzeugen und öffnen','Ergebnis im Projekt und im OneDrive-Übungsordner wiederfinden'],
 [demo('Gib Vorlage und Informationen mit.','Zeige die beiden Dateien. Erkläre, welche die Vorlage ist und welche die Fakten enthält.','Fülle 05-projektbogen.docx mit den bestätigten Lindenhof-Angaben aus. Erhalte die Struktur. Fehlende Angaben heißen „noch offen“. Nenne widersprüchliche Quellen gesondert. Gib mir eine bearbeitbare DOCX.','Vorgang LH-026 und Mara Sommer sind übernommen; Maße und Ausführungstermin bleiben offen.'),
 demo('Prüfe einen absichtlichen Stolperstein.','Vergleiche die alte Notiz mit der neueren Anfrage. Zeige, dass drei Türen nicht stillschweigend übernommen werden dürfen.','Prüfe die Türanzahl: Die ältere Notiz nennt drei, die aktuelle Anfrage zwei. Kennzeichne den Widerspruch und verwende für die aktuelle Zusammenfassung zwei, bis die Kundin bestätigt.','Die Herkunft und Unsicherheit der Angabe bleiben erkennbar.'),
 demo('Ergänze die Besichtigungsfragen.','Nutze die Recherche aus dem Vormittag. Ergänze nur die passenden Fragen.','Ergänze am Ende drei Fragen für die Besichtigung aus unserer Recherche. Ändere die übrigen bestätigten Angaben nicht.','Die Fragen passen zum konkreten Auftrag.'),
 demo('Öffne und sichere beide Formate.','Lass eine PDF erzeugen. Öffne Word und PDF, prüfe Seitenumbrüche, Tabellen und offene Felder. Speichere die geprüften Fassungen in OneDrive.',see='Die bearbeitbare Fassung und die PDF sind lesbar und wieder auffindbar.')],
 'Fülle den Projektbogen mit deinen Lindenhof-Unterlagen. Ergänze drei sinnvolle Besichtigungsfragen und speichere eine Word- und PDF-Fassung.',
 ['Lade die Vorlage und die bestätigten Projektinformationen hoch.','Lass die Felder ausfüllen und unbekannte Angaben markieren.','Prüfe besonders Türanzahl, Maße und Termine.','Öffne die fertige DOCX und die PDF und sichere beide im Übungsordner.'],
 ['Kein Preis, Maß oder Termin wurde erfunden.','Der Konflikt zur Türanzahl ist nachvollziehbar.','Word und PDF sind lesbar und am richtigen Ort gespeichert.'],
 ['Schreibe ausdrücklich „Erhalte die Vorlage; trage nur belegte Angaben ein“.','Lass dir vor dem Ausfüllen sagen, welche Felder überhaupt belegt sind.','Passt die Datei nicht? Nenne Seite, Feld und gewünschte Änderung. Lass nur diese Stelle überarbeiten.'],
 dict(ask='Im Projektbogen fehlt das Budget. Was soll ChatGPT eintragen?',options=['Ein plausibles Budget schätzen.','„Noch offen“ eintragen.'],correct=1,explain='Eine plausible Zahl wäre eine erfundene Kundenangabe. Eine Schätzung ist nur sinnvoll, wenn sie ausdrücklich beauftragt und als Schätzung markiert wird.'),
 ['05-projektbogen.docx','03-lindenhof.txt'],'Lass zusätzlich eine kurze, kundenfreundliche Zusammenfassung erstellen, ohne interne Rechenannahmen als Zusage auszugeben.','Die geprüfte PDF wird der Anhang für unseren Antwortentwurf.'),
lesson('antwort','14:00','Eine Antwort, die zu dir passt.','Entwurf mit Anhang vorbereiten.',['outlook','chatgpt'],50,
 'Jetzt kannst du Mara sinnvoll antworten. Du weißt, welche Angaben fehlen, und hast eine Übersicht vorbereitet. Du formulierst die Antwort zuerst in ChatGPT, überarbeitest sie und speicherst die fertige Fassung als Outlook-Entwurf.',
 'Erst formulieren. Dann prüfen. Dann bewusst handeln.',
 'Ein Textvorschlag in ChatGPT ist noch kein gespeicherter Outlook-Entwurf. Und ein gespeicherter Entwurf ist noch keine gesendete Mail. Diese drei Zustände trennen wir sichtbar. Du entscheidest, ob, wann und an wen wirklich etwas versendet wird.',
 'Ein geprüfter Outlook-Entwurf mit passendem Betreff und einem geprüften PDF-Anhang.',
 ['Mit Quellen einen passenden Antworttext entwerfen','Ton, Länge und Inhalt in derselben ChatGPT-Aufgabe ändern','Antwort oder neue Mail als Outlook-Entwurf speichern','Anhang gezielt hinzufügen und im Entwurf öffnen','An, CC, Antwort-an-alle, Weiterleiten und Versandfolgen unterscheiden'],
 [demo('Formuliere die Antwort.','Kehre zur Anfrage zurück. Gib ChatGPT die bestätigten Informationen und das gewünschte Ziel.','Entwirf eine freundliche Antwort an Mara Sommer. Bitte um Türmaße, Zugangsinformationen und zwei mögliche Besichtigungstermine. Sage noch keinen Preis oder Ausführungstermin zu. Zeige den Text zuerst hier.','Der Text beantwortet die Anfrage und bittet um fehlende Informationen.'),
 demo('Lass ihn nach deinem Geschmack ändern.','Ändere Länge oder Ton mit einer Folgefrage. Zeige vor und nach der Änderung.','Kürzer und etwas lockerer, aber weiter mit „Sie“. Höchstens sechs Sätze. Keine neuen Zusagen.','Der Inhalt bleibt korrekt, der Ton passt besser.'),
 demo('Speichere erst jetzt den Outlook-Entwurf.','Bei einer echten Übungsmail nutze einen Antwortentwurf. Beim fiktiven Fall speichere einen klar als ÜBUNG markierten neuen Entwurf nur an deine eigene Adresse. Keine fiktiven Empfänger anschreiben.','Speichere diesen Text als neuen Outlook-Entwurf an meine eigene E-Mail-Adresse. Betreff: ÜBUNG Lindenhof – Besichtigung vorbereiten. Noch nicht versenden.','Der Entwurf erscheint im Outlook-Ordner Entwürfe.'),
 demo('Füge die geprüfte PDF hinzu.','Wähle genau die geprüfte Datei. Das verfügbare Plugin unterstützt direkte Dateianhänge unter 3 MB. Öffne danach den Entwurf und den Anhang in Outlook.','Hänge die geprüfte Projektbogen-PDF an genau diesen Übungsentwurf an. Keine andere Datei verwenden und noch nicht versenden.','Empfänger, Text und richtiger Anhang sind im selben Entwurf sichtbar.'),
 demo('Zeige die letzte Entscheidung.','Erkläre An, CC, Antwort-an-alle und Weiterleiten am konkreten Entwurf. Für die Grundübung bleibt er gespeichert. Optional demonstrierst du nach Kontrolle eine Testmail nur an dich selbst.',see='Die Gruppe kann Entwurf und Versand unterscheiden.')],
 'Erstelle aus dem Lindenhof-Projekt eine kurze Antwort. Überarbeite sie einmal, speichere einen Übungsentwurf an dich selbst und füge die geprüfte PDF hinzu.',
 ['Formuliere eine Antwort mit den bestätigten Projektangaben.','Lass Länge oder Ton gezielt ändern.','Speichere die fertige Fassung als Übungsentwurf an deine eigene Adresse.','Füge die geprüfte PDF unter 3 MB hinzu. Öffne Entwurf und Anhang in Outlook.'],
 ['Der Empfänger ist meine eigene Adresse; der Betreff ist als ÜBUNG markiert.','Keine unbelegten Zusagen stehen im Text.','Der richtige Anhang lässt sich öffnen; die Mail bleibt ungesendet.'],
 ['Der erste Auftrag lautet nur „Zeige mir einen Antwortvorschlag“.','Ein bestehender Entwurf lässt sich nicht mit jedem Plugin direkt ändern. Überarbeite den Text vorher in ChatGPT oder anschließend selbst in Outlook.','Wenn Anhängen nicht unterstützt wird, füge die PDF selbst in Outlook hinzu. Prüfe sie trotzdem.'],
 dict(ask='ChatGPT schreibt einen guten Antworttext in den Chat. Ist die Mail schon im Outlook-Ordner Entwürfe?',options=['Ja, das passiert automatisch.','Nein, dazu muss ich sie ausdrücklich als Entwurf speichern lassen.'],correct=1,explain='Text in ChatGPT, Entwurf in Outlook und gesendete Mail sind unterschiedliche Zustände. Du kontrollierst den gewünschten Zustand im Zielprogramm.'),
 ['03-lindenhof.txt'],'Mit einer eigenen unkritischen Mail: Antwortentwurf statt neuer Mail erstellen. Antwort-an-alle nur verwenden, wenn wirklich alle Empfänger die Antwort brauchen.','Die Antwort ist vorbereitet. Jetzt planen wir die Besichtigung.'),
lesson('kalender','14:30','Ein Termin, der wirklich passt.','Besichtigung planen und ändern.',['outlook','chatgpt'],60,
 'Mara möchte eine Besichtigung. Du brauchst einen freien Zeitraum, 45 Minuten Dauer und eine klare Agenda. Ein freier Platz in deinem Kalender heißt noch nicht, dass die Kundin ebenfalls Zeit hat.',
 'Ein Terminvorschlag ist noch keine Einladung.',
 'Wir prüfen zuerst den eigenen Kalender. Dann legen wir einen Übungstermin ohne weitere Personen an. Danach verschieben wir ihn und kontrollieren die Änderung. So lernst du den vollständigen Ablauf, ohne versehentlich jemanden einzuladen.',
 'Ein angelegter und verschobener Übungstermin; anschließend sauber entfernt.',
 ['Richtigen Kalender und Zeitzone bestimmen','Termine lesen und freie Zeitfenster suchen','Dauer, Ort, Agenda und Erinnerung festlegen','Termin im eigenen Kalender anlegen und wieder öffnen','Termin ändern; Einzeltermin und Serie unterscheiden; Einladung und Absage verstehen','Übungstermin entfernen und Ergebnis kontrollieren'],
 [demo('Prüfe den richtigen Kalender.','Zeige eigenes Konto und Kalender. Übersetze „nächste Woche“ in konkrete Daten und nenne Europe/Berlin.','Zeige meine Termine am von mir gewählten Übungstag und finde ein freies Fenster von 45 Minuten zwischen 09:00 und 15:00 Uhr. Zeitzone Europe/Berlin. Noch keinen Termin anlegen.','Ein überprüfter Vorschlag mit Datum und Uhrzeit liegt vor.'),
 demo('Lege einen eigenen Übungstermin an.','Prüfe die Details. Gib dann bewusst den Auftrag zur Anlage. Keine weiteren Teilnehmer hinzufügen.','Lege nach meiner Prüfung einen Termin „ÜBUNG Lindenhof“ in meinem eigenen Kalender an: 45 Minuten zum ausgewählten Zeitpunkt, ohne weitere Teilnehmer. Beschreibung: Maße, Zugang und offene Fragen klären.','Der Termin ist im eigenen Kalender sichtbar, keine Einladung wurde verschickt.'),
 demo('Verschiebe ihn.','Wähle einen anderen freien Zeitraum und ändere denselben Termin. Prüfe Start und Ende erneut.','Verschiebe genau den Übungstermin Lindenhof auf das neue freie Zeitfenster. Behalte die Dauer von 45 Minuten. Zeige mir danach die gespeicherten Details.','Es gibt einen verschobenen Termin, nicht zwei Duplikate.'),
 demo('Räume die Übung wieder auf.','Entferne ausschließlich den eindeutig benannten Übungstermin. Erkläre: Bei einem realen Termin mit Gästen kann eine Absage Nachrichten auslösen.','Entferne den von uns angelegten Termin „ÜBUNG Lindenhof“ ohne Teilnehmer aus meinem Kalender. Andere Termine unverändert lassen.','Der Übungstermin ist entfernt, die übrigen Termine bleiben bestehen.')],
 'Finde ein freies Zeitfenster, lege dort einen eigenen Übungstermin an, verschiebe ihn und entferne ihn anschließend wieder.',
 ['Wähle konkrete Daten und prüfe deinen eigenen Kalender.','Lege nach Kontrolle einen Übungstermin ohne weitere Teilnehmer an.','Verschiebe denselben Termin und prüfe die Änderung in Outlook.','Entferne ausschließlich diesen Übungstermin und kontrolliere den Kalender.'],
 ['Ich kann Datum, Zeitzone, Dauer und Kalender benennen.','Der verschobene Termin wurde nicht doppelt angelegt.','Der Übungstermin ist wieder entfernt; niemand wurde eingeladen.'],
 ['Sag „in meinem eigenen Kalender, ohne weitere Teilnehmer“.','Nenne bei einer Änderung den exakten Titel und das bisherige Datum.','Bei einer Serie kläre zuerst: nur dieser Termin oder die ganze Serie? Für die Grundübung genügt ein Einzeltermin.'],
 dict(ask='Dein Kalender ist am Dienstag frei. Ist damit auch Mara verfügbar?',options=['Ja, ChatGPT würde einen Konflikt erkennen.','Nein, ihre Verfügbarkeit muss separat geklärt werden.'],correct=1,explain='ChatGPT kennt nur die Kalender, auf die es zugreifen darf. Ein Vorschlag ist keine Zusage aller Beteiligten.'),
 ['07-terminbrief.txt'],'Zeige eine vorhandene Besprechungseinladung und erkläre Zusagen, Vorläufig und Ablehnen. Ändere keine echte Einladung nur zu Übungszwecken.','Für die echte Besichtigung bleiben Verfügbarkeit und Zugang abzustimmen.'),
lesson('spaeter','15:30','Morgen nicht wieder von vorn.','Kontext und Aufgaben wiederverwenden.',['chatgpt'],40,
 'Die heutigen Ergebnisse sollen morgen noch helfen. Du hältst den Projektstand fest und planst eine kleine Erinnerung oder wiederkehrende Aufgabe, falls dein Konto die Funktion unterstützt.',
 'Eine Erinnerung erinnert. Ein Arbeitsauftrag arbeitet.',
 '„Erinnere mich an die Unterlagen“ ist ein Hinweis. „Fasse montags die offenen Projektfragen zusammen“ ist eine wiederkehrende KI-Aufgabe. Beides braucht eine eindeutige Zeit. Eine geplante Aufgabe braucht außerdem zugängliche Quellen und einen klaren Endpunkt.',
 'Eine gespeicherte Übergabe und eine geprüfte, anschließend deaktivierte Übungsaufgabe.',
 ['Projektstand, Quellen und nächste Schritte wiederverwendbar sichern','Erinnerung und wiederkehrende KI-Aufgabe unterscheiden','Zeit, Zeitzone, Zeitraum und gewünschtes Ergebnis festlegen','Gespeicherte Aufgabe finden und Konfiguration prüfen','Aufgabe ändern oder deaktivieren; Verfügbarkeit im Konto prüfen'],
 [demo('Sichere den Stand.','Lass aus den Arbeitsergebnissen eine kurze Übergabe erstellen. Speichere sie im Projekt.','Fasse unseren Lindenhof-Stand zusammen: erledigt, noch offen, nächste Schritte. Verweise auf die geprüften Dateien. Keine offenen Fragen als erledigt darstellen.','Du kannst am nächsten Tag ohne lange Wiederholung einsteigen.'),
 demo('Formuliere zwei unterschiedliche Aufträge.','Zeige eine Erinnerung und daneben eine wiederkehrende Zusammenfassung. Lass die Gruppe den Unterschied erklären.','Zeige zuerst die Einrichtung: vier Wochen lang montags um 08:30 Uhr, Europe/Berlin, offene Fragen aus dem Projekt Lindenhof zusammenfassen. Keine Mails versenden.','Zeit, Quelle, Ergebnis und Enddatum sind eindeutig.'),
 demo('Prüfe die gespeicherte Aufgabe.','Richte eine kurze Übungsaufgabe nur ein, wenn sie im Konto verfügbar ist. Öffne sie in der Aufgabenverwaltung und prüfe Zeit, Wiederholung und Quelle.',see='Ein Chattext allein ist noch kein Nachweis für eine gespeicherte Planung.'),
 demo('Deaktiviere die Übung.','Zeige, wo eine Aufgabe beendet oder deaktiviert wird. Verlasse die Übung mit einem aufgeräumten Konto.',see='Keine unbeabsichtigte Wiederholung bleibt aktiv.')],
 'Speichere eine kurze Projektübergabe. Formuliere eine Erinnerung und eine wiederkehrende Aufgabe. Richte eine als Übung ein, prüfe sie und deaktiviere sie wieder, sofern dein Konto das unterstützt.',
 ['Sichere erledigte Punkte, offene Fragen und nächste Schritte im Projekt.','Formuliere beide Varianten mit konkreter Zeit und Zeitzone.','Prüfe eine gespeicherte Übungsaufgabe in der Aufgabenverwaltung.','Deaktiviere sie wieder. Fehlt die Funktion, bespreche den fertigen Auftrag mit der Gruppe.'],
 ['Meine Übergabe ist im Projekt wieder auffindbar.','Ich kann Erinnerung und wiederkehrenden Arbeitsauftrag unterscheiden.','Ich habe eine vorhandene Planung geprüft und beendet – oder die fehlende Funktion klar festgehalten.'],
 ['Nenne bei einer Wiederholung immer, wie lange sie laufen soll.','Die Quelle muss zur Ausführungszeit erreichbar sein. Frage nach, wenn der Zugriff unklar ist.','Wenn die Funktion fehlt: ITP kann Konto und Freigaben prüfen. Ein Text im Chat ersetzt keine gespeicherte Aufgabe.'],
 dict(ask='ChatGPT beschreibt eine Montagsaufgabe. Reicht das als Beleg, dass sie wirklich eingerichtet ist?',options=['Ja, die Beschreibung ist die Bestätigung.','Nein, ich öffne die gespeicherte Aufgabe und prüfe die Einstellungen.'],correct=1,explain='Du prüfst den Zustand dort, wo die Aufgabe verwaltet wird. Dasselbe Prinzip gilt für Mailentwürfe, Dateien und Termine.'),
 ['07-terminbrief.txt'],'Ändere an einer eigenen Übungsaufgabe die Uhrzeit und kontrolliere die neue Einstellung, bevor du sie deaktivierst.','Dein Projekt ist auch nach dem Seminar wieder verwendbar.'),
lesson('abschluss','16:00','Du übernimmst den Auftrag.','Alles selbst verbinden.',['chatgpt','excel','outlook','onedrive'],60,
 'Zum Schluss kommt eine neue Nachricht im selben Projekt: Für die fiktive Montageposition werden nun 200 statt 100 Einheiten benötigt. Eine andere Person muss deinen Projektstand übernehmen können.',
 'Du wählst die Werkzeuge passend zum Ziel.',
 'Jetzt gibt es keinen vorgegebenen Klickweg. Du entscheidest, welche Quellen du brauchst, welche Dateien sich ändern und welche Handlungen erst nach einer Kontrolle erfolgen sollen. Entscheidend ist ein nachvollziehbares Ergebnis, nicht ein bestimmter Wortlaut im Auftrag.',
 'Ein verständliches Übergabepaket für Lindenhof mit aktualisierter Rechnung, Dokument und Antwortentwurf.',
 ['Mehrere Werkzeuge zu einem Ablauf verbinden','Änderung von ursprünglichen Angaben trennen','Ergebnisse prüfen, Fehler korrigieren und Quellen nennen','Speicherorte und nächste Schritte nachvollziehbar übergeben','Eine eigene sinnvolle Anwendung für den nächsten Arbeitstag formulieren'],
 [demo('Lies die neue Nachricht.','Zeige nur den Änderungsauftrag. Lass die Gruppe selbst benennen, welche bisherigen Ergebnisse betroffen sind.',see='Die Menge ändert sich; bestätigte Kundendaten und unbekannte Termine bleiben unverändert.'),
 demo('Vereinbart, woran man ein gutes Ergebnis erkennt.','Zeige die vier Ergebnismerkmale, ohne den Lösungsweg vorzugeben: korrekte Rechnung, aktueller Projektstand, geprüfte Dateien, ungesendeter Entwurf.',see='Alle kennen das Ziel. Danach wird eigenständig gearbeitet.')],
 'Aktualisiere Lindenhof für 200 Montageeinheiten. Erstelle ein nachvollziehbares Übergabepaket und einen ungesendeten Übungsentwurf an dich selbst. Wähle deinen eigenen Weg.',
 ['Lies 10-aenderung-und-uebergabe.txt und entscheide, was geändert werden muss.','Aktualisiere Vergleich und Projektunterlagen. Erhalte die bisherigen Versionen.','Speichere die geprüften Dateien in deinem OneDrive-Übungsordner.','Entwirf eine kurze Antwort an dich selbst und bereite die Übergabe vor. Lass eine andere Person dein Ergebnis nachvollziehen.'],
 ['Der Vergleich für 200 Einheiten ergibt C = 2.540 € netto unter der genannten Annahme.','Die Dateien sind aktuell, prüfbar und eindeutig benannt.','Mein Entwurf ist ungesendet; keine Übungstermine oder Wiederholungen bleiben aktiv.','Eine andere Person versteht meinen Projektstand und die nächsten Schritte.'],
 ['Beginne mit „Welche meiner bisherigen Ergebnisse sind von der neuen Menge betroffen?“','Bearbeite erst die Rechnung, dann die davon abhängigen Texte.','Wenn du festhängst: Fasse den aktuellen Stand zusammen und gib ChatGPT nur den nächsten kleinen Schritt.'],
 dict(ask='Was nimmst du als wichtigste Gewohnheit mit?',options=['Eine gute Formulierung sofort übernehmen.','Auftrag klar beschreiben, Ergebnis prüfen und bei Bedarf nachsteuern.'],correct=1,explain='Du musst nicht jeden Klick auswendig kennen. Du brauchst ein klares Ziel, die richtigen Quellen und einen eigenen Kontrollblick.'),
 ['10-aenderung-und-uebergabe.txt'],'Formuliere eine konkrete Aufgabe für deinen nächsten echten Arbeitstag: Ausgangslage, Ziel, Quelle, Ausgabe und Kontrollpunkt.','Deine fertigen Ergebnisse bleiben in deiner eigenen Umgebung.')
]
for i,l in enumerate(lessons):
 l['number']=i+1;l['day']=1 if i<5 else 2
 l['rhythm']={'explain':8,'show':12 if i!=9 else 5,'do':l['minutes']-28 if i!=9 else 37,'check':8 if i!=9 else 10}
plan={
 'title':'Ein Arbeitstag. Mehr geschafft.',
 'subtitle':'Du begleitest einen Kundenauftrag vom Posteingang bis zur Übergabe. Mit ChatGPT, deinen Programmen und deinen eigenen Entscheidungen.',
 'case':'Lindenhof · Umbau',
 'promise':'Am Ende kannst du eine Arbeitsaufgabe klar beschreiben, passende Quellen mitgeben, Ergebnisse prüfen und den nächsten Schritt selbst steuern.',
 'environment':'Du arbeitest in deiner eigenen ChatGPT-Umgebung. Diese Website erklärt den Ablauf und stellt Übungsdateien bereit. Sie liest keine Mails, verbindet keine Konten und führt keine KI-Aufträge aus.',
 'lessons':lessons,
 'schedule':[
 {'day':1,'title':'Verstehen & vorbereiten','items':[['09:00','Ankommen, Technik prüfen, Ziel klären','15 min'],['09:15','1 · Mail verstehen','50 min'],['10:05','2 · Projekt anlegen','50 min'],['10:55','Pause','15 min'],['11:10','3 · Dateien bearbeiten und ablegen','70 min'],['12:20','Mittagspause','60 min'],['13:20','4 · Recherchieren und Browser steuern','55 min'],['14:15','Pause','15 min'],['14:30','5 · Excel vergleichen und prüfen','70 min'],['15:40','Ergebnisse sichern und offene Fragen klären','20 min']]},
 {'day':2,'title':'Fertigstellen & selbst übernehmen','items':[['09:00','Wieder ankommen: Projekt selbst wiederfinden','15 min'],['09:15','6 · Projektbogen ausfüllen','60 min'],['10:15','7 · Antwort und Anhang vorbereiten','50 min'],['11:05','Pause','15 min'],['11:20','8 · Kalender vollständig üben','60 min'],['12:20','Mittagspause','60 min'],['13:20','9 · Übergabe und geplante Aufgaben','40 min'],['14:00','Pause','15 min'],['14:15','10 · Eigenständiger Abschlussauftrag','60 min'],['15:15','Ergebnisse vorstellen, aufräumen und Transfer','45 min']]}
 ],
 'glossary':{'Auftrag':'Das, was ChatGPT für dich erledigen soll. Du beschreibst es in deinen Worten.','Projekt':'Eine Arbeitsmappe für zusammengehörige Aufgaben, Dateien und Vorgaben.','Plugin':'Eine Verbindung oder Erweiterung, mit der ChatGPT ein anderes Programm nutzen kann.','Quelle':'Die Datei, Mail oder Website, auf der eine Aussage beruht.','Entwurf':'Eine vorbereitete Mail, die noch nicht versendet wurde.','Hochladen':'Eine Datei von deinem Computer in eine Anwendung geben.','Herunterladen':'Eine Datei aus einer Anwendung auf deinen Computer holen.','DOCX':'Eine Word-Datei, die du weiter bearbeiten kannst.','PDF':'Ein Format zum Lesen und Weitergeben; Layout und Inhalte trotzdem prüfen.','XLSX':'Eine Excel-Arbeitsmappe mit Tabellenblättern, Formeln und Formatierung.','CSV':'Eine einfache Datentabelle. Sie bewahrt keine komplette Excel-Arbeitsmappe.','Freigabe':'Deine bewusste Entscheidung, dass eine bestimmte Handlung ausgeführt werden darf.'}
}
Path('public/curriculum.json').write_text(json.dumps(plan,ensure_ascii=False,indent=2))
# Participant-facing, printable document generated from the same source.
md=['# Ein Arbeitstag mit KI – Lernplan','',plan['subtitle'],'',plan['environment'],'','Empfehlung: zwei Tage, jeweils 09:00–16:00 Uhr. Die Zeiten 08:30–16:00 an den Stationen gehören zum fiktiven Arbeitstag, nicht zum Seminarplan.','', '## Lernziel',plan['promise'],'','## Ablauf pro Station','8 Minuten Prinzip verstehen; etwa 12 Minuten Vorführung in der echten ChatGPT-Umgebung; eigene Aufgabe; Ergebnis zeigen und prüfen. Die Abschlussstation arbeitet mit mehr Eigenzeit.','']
for day in plan['schedule']:
 md+=['## Tag '+str(day['day'])+' – '+day['title']]+['- '+ ' · '.join(r) for r in day['items']]+['']
for l in lessons:
 md += ['## '+str(l['number'])+'. '+l['title'],l['why'],'', '**Das lernen wir:**']+['- '+s for s in l['skills']]+['','**Das zeigst du live in deiner Umgebung:**']
 for j,d in enumerate(l['demos'],1):md += [str(j)+'. '+d['title']+' '+d['action']]+(['   Auftrag: '+d['prompt']] if d['prompt'] else [])
 md += ['','**Eigene Aufgabe:** '+l['mission'],'','**Ergebnis prüfen:**']+['- '+s for s in l['checks']]+['','**Für den nächsten Schritt:** '+l['carry'],'']
